(function (w, d) {
  'use strict';

  // ===== Guard / reuse =====
  const PREV = w.UCM || {};
  const REG = PREV.__REGISTRY instanceof Map ? PREV.__REGISTRY : new Map();
  let CSS_INJECTED_FOR = typeof PREV.__CSS_INJECTED_FOR === 'string' ? PREV.__CSS_INJECTED_FOR : '';
  const REG_EL = new Map(); // el -> { sel, cfg, handlers }

  // ===== Defaults =====
  const DEFAULTS = {
    effect: 'words',            // 'lines' | 'words' | 'letters'
    randomize: false,           // хаос внутри строки
    baseDelay: 200,             // мс (если Basic выключен)
    delayBetweenLines: 60,      // мс
    parallelLines: true,        // строки параллельно
    parallelLineStagger: 60,    // мс (шаг старта строк в параллели)
    letterWordDelay: 30,        // мс (шаг между словами/буквами)
    threshold: 0.4,             // доля видимости для старта
    preferBasicDelay: true,     // брать задержку из Tilda Basic если есть
    autoReset: false,           // авто-сброс при выходе из viewport
    debug: false                // лог в консоль
  };
  let CONFIG = { ...DEFAULTS, ...(PREV.defaults || {}) };

  // ===== Utils =====
  const ready = (cb) =>
    d.readyState !== 'loading'
      ? cb()
      : d.addEventListener('DOMContentLoaded', cb, { once: true });

  const getAtom = (el) => {
    if (!el) return null;
    if (el.classList?.contains('tn-atom')) return el;
    return el.querySelector?.('.tn-atom') || null;
  };

  const toMs = (v) => Math.max(0, parseFloat(String(v).replace(',', '.')) * 1000 || 0);
  const hasBasic = (el) => el?.hasAttribute?.('data-animate-style');
  const readBasicDelay = (el, fallback) =>
    hasBasic(el) ? toMs(el.getAttribute('data-animate-delay') ?? '0') : fallback;

  // — НЕ убиваем авторскую opacity
  function neutralizeBasic(el) {
    if (!el) return;
    el.style.transition = 'none';
    el.style.transform  = 'none';
    const atom = getAtom(el);
    if (atom) {
      atom.style.transition = 'none';
      atom.style.transform  = 'none';
    }
  }

  // — CSS inject (без opacity:1!important)
  function injectBasicNeutralizerFor(selectors) {
    if (!selectors || !selectors.length) return;
    const key = '1.3.1-gsap|' + selectors.slice().sort().join('|');
    if (key === CSS_INJECTED_FOR) return;
    CSS_INJECTED_FOR = key;

    const css = `
      ${selectors.map((s)=>`${s}.t-animate,${s}.t-animate_wait,${s}.t-animate_started`).join(',')}
        {transform:none!important;transition:none!important;}
      ${selectors.map((s)=>`${s} [data-animate-style],${s} [data-animate-sbs-opts]`).join(',')}
        {animation:none!important;transition:none!important;}
      ${selectors.map((s)=>`${s} .tn-atom`).join(',')}
        {transform:none!important;transition:none!important;}
      .uc-line{display:block;overflow:visible;line-height:inherit;}
      .uc-line.uc-gap{margin-top:0;}
      .uc-word,.uc-space,.uc-letter{display:inline-block;white-space:pre;will-change:opacity,transform,filter;}
    `.replace(/\s+/g,' ');

    const tag = d.createElement('style');
    tag.type = 'text/css';
    tag.appendChild(d.createTextNode(css));
    d.head.appendChild(tag);
  }

  // — безопасное разбиение сущностей при letters
  const ENTITY_RE = /&[a-zA-Z0-9#]+;/g;
  function splitWithEntities(text) {
    return text
      .replace(ENTITY_RE, '|$&|')
      .split('|')
      .flatMap((p) => (p.length > 1 && /^&.*;$/.test(p) ? [p] : [...p]));
  }

  // — получить «потоковый» узел для измерения offsetTop (учёт <em>/<strong>/<span> и т.п.)
  function getFlowNode(node){
    if (!(node instanceof Element)) return null;
    if (node.matches('.uc-word,.uc-space')) return node;
    let cur = node.firstElementChild;
    while (cur && !cur.matches('.uc-word,.uc-space')) cur = cur.firstElementChild;
    return cur || (node.matches('.uc-line') ? node : null);
  }

  // — обёртки .uc-word/.uc-letter и пост-лайн по offsetTop
  function ensureWrapped(atom, mode) {
    if (!atom || atom.__ucWrapped) return;

    const html = atom.innerHTML.replace(/\[gap\]/g, '<span class="__gap-marker"></span>');
    const parts = html.replace(/(<[^>]+>)/g, '|$1|').split('|').filter(Boolean);

    let out = '';
    for (const part of parts) {
      if (part === '<span class="__gap-marker"></span>' || /^<br\s*\/?>$/i.test(part)) { out += part; continue; }
      if (part.startsWith('<') && part.endsWith('>')) { out += part; continue; }

      const tokens = part.split(/(\u00A0| )/);
      for (const tok of tokens) {
        if (tok === '\u00A0' || tok === ' ') {
          out += `<span class="uc-space">${tok}</span>`;
        } else if (mode === 'letters') {
          const letters = splitWithEntities(tok).map((ch)=>`<span class="uc-letter">${ch}</span>`).join('');
          out += `<span class="uc-word">${letters}</span>`;
        } else {
          out += `<span class="uc-word">${tok}</span>`;
        }
      }
    }

    const prevVis = atom.style.visibility;
    atom.style.visibility = 'hidden';
    atom.innerHTML = out;

    // offsetTop → группировка в строки (учёт декораторов)
    requestAnimationFrame(() => {
      const kids = [...atom.childNodes];
      const lines = [];
      let row = [];
      let top = null;

      for (const node of kids) {
        if (node.nodeType === 1 && node.classList?.contains('__gap-marker')) {
          if (row.length) lines.push({ nodes: row, isGap: false });
          lines.push({ nodes: null, isGap: true });
          row = []; top = null; continue;
        }
        if (!(node instanceof Element)) continue;
        if (node.tagName === 'BR') continue;

        const flow = getFlowNode(node);
        if (!flow) continue;

        const t = flow.offsetTop;
        if (top === null) top = t;
        if (t !== top) { lines.push({ nodes: row, isGap: false }); row = []; top = t; }
        row.push(node); // переносим весь декоратор
      }
      if (row.length) lines.push({ nodes: row, isGap: false });

      // — «прилипание» ведущих пробелов к предыдущей строке
      for (let i = 1; i < lines.length; i++) {
        const L = lines[i];
        const P = lines[i-1];
        if (L.isGap || !P || P.isGap || !L.nodes?.length) continue;
        const first = L.nodes[0];
        const flowFirst = getFlowNode(first);
        if (!flowFirst) continue;
        if (flowFirst.matches('.uc-space')) {
          L.nodes.shift();
          P.nodes.push(first);
          if (L.nodes.length === 0) { lines.splice(i, 1); i--; }
        }
      }

      const frag = d.createDocumentFragment();
      for (const item of lines) {
        const div = d.createElement('div');
        div.className = item.isGap ? 'uc-line uc-gap' : 'uc-line';
        if (item.isGap) div.innerHTML = '&nbsp;';
        else item.nodes.forEach((n)=> div.appendChild(n));
        frag.appendChild(div);
      }
      atom.textContent = '';
      atom.appendChild(frag);

      atom.style.visibility = prevVis || 'visible';
      atom.__ucWrapped = mode || 'words';
      atom.__ucLinesBuilt = true;
    });
  }

  // — чтение классовых тогглов
  function readTogglesFrom(el, baseCfg) {
    const o = { ...baseCfg };
    const cls = [...el.classList];
    const has = (x) => el.classList.contains(x);
    const hit = (re) => cls.find((c) => re.test(c));

    if (has('uc-unit-lines')) o.effect = 'lines';
    if (has('uc-unit-words')) o.effect = 'words';
    if (has('uc-unit-letters')) o.effect = 'letters';
    if (has('uc-order-chaos')) o.randomize = true;
    if (has('uc-lines-serial')) o.parallelLines = false;

    const stg = hit(/^uc-stagger-(\d+)$/);
    if (stg) o.letterWordDelay = +stg.split('-').pop();

    const thr = hit(/^uc-threshold-(\d+)$/);
    if (thr) o.threshold = Math.min(1, Math.max(0, +thr.split('-').pop() / 100));

    return o;
  }

  const decideUnit = (cfg) =>
    (cfg.effect === 'letters') ? 'letters' : (cfg.effect === 'lines') ? 'lines' : 'words';

  // — планировщик по линиям/словам/буквам (исключаем .uc-gap)
  function scheduleByLines(atom, cfg, unit, cb /* (target, whenMs) */) {
    const lineNodes = [...atom.querySelectorAll('.uc-line:not(.uc-gap)')];
    let cumulative = 0;

    lineNodes.forEach((line, i) => {
      const targets =
        unit === 'letters'
          ? [...line.querySelectorAll('.uc-letter')]
          : unit === 'words'
          ? [...line.querySelectorAll('.uc-word,.uc-space')]
          : [line];

      const step = unit === 'lines' ? 0 : cfg.letterWordDelay;
      let order = targets.map((_, k) => k);
      if (cfg.randomize) order.sort(() => Math.random() - 0.5);

      const lineDelay = cfg.parallelLines ? cumulative + i * cfg.parallelLineStagger : cumulative;

      targets.forEach((t, j) => {
        const idx = cfg.randomize ? order[j] : j;
        cb(t, lineDelay + idx * step);
      });

      if (!cfg.parallelLines) {
        cumulative += unit === 'lines'
          ? cfg.delayBetweenLines
          : targets.length * step + cfg.delayBetweenLines;
      }
    });
  }

  // — Mini helpers
  const delayed = (ms, fn) => {
    const hasGSAP = !!w.gsap && !!w.gsap.delayedCall;
    return hasGSAP ? w.gsap.delayedCall(ms / 1000, fn) : setTimeout(fn, ms);
  };

  // ===== Public API =====
  const UCM = {
    version: '1.3.1-gsap',
    defaults: { ...CONFIG },

    config(overrides = {}) {
      CONFIG = { ...CONFIG, ...overrides };
      this.defaults = { ...CONFIG };
      if (CONFIG.debug) {
        try { console.info('[UCM] config', this.defaults); } catch(_) {}
      }
      return this;
    },

    register(selector, handlers) {
      if (!selector || !handlers || typeof handlers.prepare !== 'function' || typeof handlers.run !== 'function') {
        return this;
      }
      REG.set(selector, handlers);
      return this;
    },
    unregister(selector) { REG.delete(selector); return this; },

    init(selector) {
      injectBasicNeutralizerFor([...REG.keys()]);

      const entries = selector
        ? [...d.querySelectorAll(selector)]
            .map((el) => ({ el, sel: [...REG.keys()].find((s) => el.matches(s)) }))
            .filter((x) => x.sel)
        : [...REG.keys()].flatMap((sel) => [...d.querySelectorAll(sel)].map((el) => ({ sel, el })));

      entries.forEach(({ sel, el }) => {
        const atom = getAtom(el);
        if (!atom) return;

        const cfg = readTogglesFrom(el, CONFIG);

        // prepare (wrap → build lines)
        try { REG.get(sel).prepare(el, cfg, this.util); } catch (e) { console.warn('[UCM prepare]', e); }

        // сохранить запись для IO
        REG_EL.set(el, { sel, cfg, handlers: REG.get(sel) });

        // наблюдать (единый IO)
        START_IO.observe(el);

        if (CONFIG.debug) {
          try { console.info('[UCM] init element', { sel, el, cfg }); } catch(_) {}
        }
      });

      return this;
    },

    util: {
      ready, getAtom, toMs, hasBasic, readBasicDelay,
      neutralizeBasic, injectBasicNeutralizerFor,
      splitWithEntities, ensureWrapped, scheduleByLines, decideUnit,
      // utility: ResizeObserver c debounce
      watchAtom(atom, reflow, waitMs = 120) {
        if (!('ResizeObserver' in w) || !atom) return;
        let t; let prevW = atom.offsetWidth, prevH = atom.offsetHeight;
        const ro = new ResizeObserver(() => {
          clearTimeout(t);
          t = setTimeout(() => {
            if (!atom.isConnected) return;
            const w0 = atom.offsetWidth, h0 = atom.offsetHeight;
            if (w0 === prevW && h0 === prevH) return;
            prevW = w0; prevH = h0;
            try { reflow?.(); } catch(_) {}
          }, waitMs);
        });
        ro.observe(atom);
        atom.__ucRO = ro;
      },
      // точечный CSS-инжект для эффектов
      injectCSS(id, css) {
        if (!id || !css) return;
        if (d.getElementById(id)) return;
        const tag = d.createElement('style');
        tag.id = id; tag.type = 'text/css';
        tag.appendChild(d.createTextNode(css));
        d.head.appendChild(tag);
      }
    },

    __REGISTRY: REG,
    __CSS_INJECTED_FOR: CSS_INJECTED_FOR,
    __coreLoaded: true
  };

  // ===== Единый IntersectionObserver (старт/сброс) =====
  const START_IO = new IntersectionObserver((ents) => {
    ents.forEach((ent) => {
      const el = ent.target;
      const rec = REG_EL.get(el);
      if (!rec) return;
      const { cfg, handlers } = rec;
      const atom = getAtom(el);
      if (!atom) return;

      if (ent.isIntersecting) {
        // Запуск эффекта с задержкой (BasicDelay → fallback)
        const delay = cfg.preferBasicDelay ? readBasicDelay(el, cfg.baseDelay) : cfg.baseDelay;
        delayed(delay, function tryStart() {
          if (!atom.__ucLinesBuilt) { requestAnimationFrame(tryStart); return; }
          if (el.__ucRan) return;
          el.__ucRan = true;
          neutralizeBasic(el);
          try { handlers.run(el, cfg, UCM.util); } catch (e) { console.warn('[UCM run]', e); }
          // Если autoreset выключен — можно перестать наблюдать, иначе оставляем для отслеживания выхода
          if (!cfg.autoReset) START_IO.unobserve(el);
          if (CONFIG.debug) { try { console.info('[UCM] run', el); } catch(_){} }
        });
      } else {
        // Выход из viewport → авто-сброс
        if (cfg.autoReset && el.__ucRan && typeof handlers.reset === 'function') {
          el.__ucRan = false;
          try { handlers.reset(el, cfg, UCM.util); } catch (_) {}
          if (CONFIG.debug) { try { console.info('[UCM] reset', el); } catch(_){} }
        }
      }
    });
  }, { threshold: [0, CONFIG.threshold, 1] });

  // ===== Console banner =====
  (function banner() {
    if (w.__UCM_BANNER__) return;
    w.__UCM_BANNER__ = true;
    try { console.log('%cUC Motion core v' + UCM.version + ' — ready', 'color:#25EDFF;font-weight:600;'); } catch(_) {}
  })();

  w.UCM = UCM;
})(window, document);
